38| * @param {Function} [props.onDirtyChange] - Called with true/false as edits are made or saved.
39| * @param {Function} [props.onRequestSection] - Requests a tab switch (the Project tab's docs-repo summary jumps to Files & Repos through it).
40| * @example <ProjectSettingsForm project={project} projectId="p1" onProjectUpdated={select} section="aliases" onDirtyChange={setDirty} />
41| ***/
42|export function ProjectSettingsForm({
43|  project,
44|  projectId,
