	// back where it was (soft reset keeps the index/worktree untouched).
	await runGit(workdir, ["branch", recoveredTo]);
	if (branch && branch !== "HEAD" && headBefore) {
		await runGit(workdir, ["reset", "--soft", headBefore]).catch(() => {});
