#!/usr/bin/env node
// Live UI proof for "Cant see settings in the Ui" (task 7f6220c3).
// Serves THIS branch's frontend source via vite + a stub API, then drives
// headless Chromium (Playwright) at a realistic 1280x720 viewport and
// asserts the docs-repo setting is actually visible on every surface:
//   1. Create dialog: Advanced open by default, URL field in viewport.
//   2. Adopt dialog: same + local-path field.
//   3. Settings -> Files & Repos: Separate Docs Repository block.
//   4. Settings -> Project tab: On/Off summary row + jump button.
//   5. Settings search: "stealth" finds the entry; selection jumps.
// Screenshots land in docs/tasks/<taskId>/ as stage4-proof-*.png.
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import { createRequire } from 'node:module';
const require = createRequire('/home/[REDACTED]/.kainbain/runner-work/kb-7f6220c3-c536-489c-b952-9858aae9ef21/package.json');
const { chromium } = require('playwright');

const WD = '/home/[REDACTED]/.kainbain/runner-work/kb-7f6220c3-c536-489c-b952-9858aae9ef21';
const FE = path.join(WD, 'frontend');
const OUT = path.join(WD, 'docs/tasks/7f6220c3-c536-489c-b952-9858aae9ef21');
const API_PORT = 3901;
const VITE_PORT = 5173;
const BASE = `http://127.0.0.1:${VITE_PORT}`;

const PROJECT = {
  id: 'demo-p',
  name: 'Demo Project',
  cwd: '/tmp/demo-project',
  docsRepo: {
    url: 'https://git.example.com/me/demo-kainbain-docs.git',
    localPath: '/tmp/demo-project-kainbain-docs',
  },
  updatedAt: '2026-11-20T00:00:00.000Z',
  harness: '',
  defaultModel: '',
};

// ---- Stub API ------------------------------------------------------------
const api = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://x');
  const p = url.pathname;
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', `http://127.0.0.1:${VITE_PORT}`);
  res.setHeader('Access-Control-Allow-Credentials', 'true');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PATCH,PUT,DELETE,OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'content-type,authorization');
  if (req.method === 'OPTIONS') { res.end('{}'); return; }
  if (p === '/projects') { res.end(JSON.stringify([PROJECT])); return; }
  if (p === '/projects/demo-p') { res.end(JSON.stringify(PROJECT)); return; }
  if (p === '/status') { res.end(JSON.stringify({ build: { commit: 'proof' }, status: 'ok' })); return; }
  if (p === '/compute/models') {
    res.end(JSON.stringify({
      models: [],
      harnesses: [{ id: 'pi', label: 'Pi', isDefault: true, models: [], modelSelection: 'list' }],
    }));
    return;
  }
  if (p === '/runners/models/catalogue' || p === '/compute/status' || p === '/status/health') {
    res.end(JSON.stringify({}));
    return;
  }
  if (p === '/skills' || p === '/onboarding') { res.end(JSON.stringify([])); return; }
  res.statusCode = 404;
  res.end(JSON.stringify({ error: 'stub-404' }));
});

// ---- vite dev server -----------------------------------------------------
const viteBin = path.join(FE, 'node_modules/.bin/vite');
const vite = spawn(process.execPath, [viteBin, '--port', String(VITE_PORT), '--host', '127.0.0.1', '--strictPort'], {
  cwd: FE,
  env: { ...process.env, VITE_API_BASE: `http://localhost:${API_PORT}` },
  stdio: ['ignore', 'pipe', 'pipe'],
});
let viteOut = '';
vite.stdout.on('data', (d) => { viteOut += d; });
vite.stderr.on('data', (d) => { viteOut += d; });

async function waitFor(fn, what, ms = 45000) {
  const t0 = Date.now();
  for (;;) {
    try { if (await fn()) return; } catch {}
    if (Date.now() - t0 > ms) throw new Error(`timeout waiting for ${what}\n--- vite output ---\n${viteOut.slice(-2000)}`);
    await new Promise((r) => setTimeout(r, 300));
  }
}

const results = [];
function check(name, ok, detail = '') {
  results.push({ name, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) process.exitCode = 1;
}

let browser;
try {
  await new Promise((r) => api.listen(API_PORT, '127.0.0.1', r));
  console.log(`stub API on :${API_PORT}`);
  await waitFor(async () => path.join(FE, 'node_modules/.bin/vite') && viteOut.includes('Local:'), 'vite ready');
  console.log('vite ready');

  browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', (e) => console.log('PAGEERROR:', e.message.slice(0, 200)));
  page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE-ERR:', m.text().slice(0, 300)); });
  page.on('requestfinished', async (r) => {
    const u = r.url();
    if (u.includes(':3901') || u.includes(':5173')) {
      const res = await r.response().catch(() => null);
      console.log(`REQ ${r.method()} ${new URL(u).pathname} -> ${res ? res.status() : '?'}`);
    }
  });

  // ---- 1. Create dialog --------------------------------------------------
  await page.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' });
  await page.getByRole('button', { name: /Project:/ }).waitFor({ timeout: 20000 });
  await page.getByRole('button', { name: /Project:/ }).click();
  await page.getByText('+ New Project').click();
  const createAdvancedBtn = page.getByRole('button', { name: /Advanced options: separate docs repo/ });

